<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import type { DefaultYsm,YsmAsset } from '@shared/ysm'
import { ysmApi } from '../ysmApi'
import { errText } from '../api'
import { selectedResourceTarget,selectedLauncherInstance,store,toast } from '../store'
import YsmViewer3D from './YsmViewer3D.vue'
const assets=ref<YsmAsset[]>([]),state=ref<DefaultYsm>({enabled:false,previewOnHome:true}),busy=ref(''),error=ref('')
const animationNames=ref<string[]>([])
const selected=computed(()=>assets.value.find(a=>a.id===state.value.assetId))
const target=computed(()=>{const v=selectedResourceTarget.value;return v?{id:v.id,folder:v.folder||store.settings?.activeFolder||store.settings?.gameDir||''}:undefined})
async function act(name:string,fn:()=>Promise<void>){if(busy.value)return;busy.value=name;error.value='';try{await fn()}catch(e){error.value=errText(e)}finally{busy.value=''}}
async function save(change:Partial<DefaultYsm>){await act('save',async()=>{state.value=await ysmApi.setDefaults({...state.value,...change});window.dispatchEvent(new Event('nomadcraft:ysm-defaults'))})}
async function importModel(){await act('import',async()=>{const model=await ysmApi.import();if(!model)return;assets.value=await ysmApi.list();state.value=await ysmApi.setDefaults({...state.value,assetId:model.id,texture:model.textures.includes('default')?'default':model.textures[0],animation:undefined});window.dispatchEvent(new Event('nomadcraft:ysm-defaults'));toast('YSM 模型已导入','success')})}
async function install(){if(!target.value||!selected.value)return;await act('install',async()=>{const result=await ysmApi.install(target.value!,selected.value!.id);toast('模型资源已同步：'+result.modelId+'。游戏内外观选择由 YSM 保存。','success')})}
onMounted(()=>void act('load',async()=>{[assets.value,state.value]=await Promise.all([ysmApi.list(),ysmApi.defaults()])}))
</script>
<template><section class="card default-ysm"><header class="ysm-header"><div><h2>默认 YSM 模型</h2><p>为支持 YSM 的游戏实例准备同一套模型，并在首页预览。</p></div><button class="btn btn-primary" :disabled="!!busy" @click="importModel">{{busy==='import'?'正在解析模型…':'导入模型…'}}</button></header><p v-if="error" class="ysm-error" role="alert">{{error}}</p><div class="ysm-layout"><div class="ysm-preview"><YsmViewer3D v-if="selected" :asset-id="selected.id" :texture="state.texture" :default-animation="state.animation" @animations="animationNames=$event"/><div v-else class="ysm-empty">导入 .ysm 或模型 ZIP，查看立体模型与自带动作</div></div><div class="ysm-form"><label>默认模型<select :value="state.assetId||''" :disabled="!!busy" @change="save({assetId:($event.target as HTMLSelectElement).value,texture:undefined,animation:undefined})"><option value="" disabled>选择已导入的模型</option><option v-for="asset in assets" :key="asset.id" :value="asset.id">{{asset.name}} · {{asset.modelId}}</option></select></label><label v-if="selected">模型贴图<select :value="state.texture||selected.textures[0]" :disabled="!!busy" @change="save({texture:($event.target as HTMLSelectElement).value})"><option v-for="texture in selected.textures" :key="texture" :value="texture">{{texture}}</option></select></label><label v-if="selected">默认播放动作<select :value="state.animation||''" :disabled="!!busy||!animationNames.length" @change="save({animation:($event.target as HTMLSelectElement).value||undefined})"><option value="">自动选择待机 / 行走</option><option v-for="name in animationNames" :key="name" :value="name">{{name}}</option></select><small>重新进入首页或打开此模型时自动播放，不改变游戏内动作。</small></label><div v-if="selected" class="ysm-summary"><span>{{selected.textures.length}} 套贴图</span><span>{{selected.animationCount}} 个模型动作</span></div><label class="ysm-switch"><span><b>启动时自动安装模型</b><small>仅对已安装 YSM 的实例生效</small></span><span class="switch"><input type="checkbox" :checked="state.enabled" :disabled="!!busy||!selected" @change="save({enabled:($event.target as HTMLInputElement).checked})"><span class="switch-ui"></span></span></label><label class="ysm-switch"><span><b>首页默认展示 YSM</b><small>启用默认模型后，仍可随时切回普通皮肤预览</small></span><span class="switch"><input type="checkbox" :checked="state.previewOnHome" :disabled="!!busy" @change="save({previewOnHome:($event.target as HTMLInputElement).checked})"><span class="switch-ui"></span></span></label><p class="ysm-note">模型安装与游戏内换肤是两件事。当前 YSM 将所选外观保存在服务器中，启动器不会覆盖旧存档的选择或整服默认模型。首次使用请在 YSM 中选择，后续由游戏记住。</p><button class="btn btn-ghost" :disabled="!!busy||!selected||!target" @click="install">{{busy==='install'?'正在同步…':'立即安装到当前实例'}}</button><small v-if="target" class="ysm-target">当前实例：{{selectedLauncherInstance?.customName||target.id}}</small></div></div></section></template>
<style scoped>.default-ysm{padding:22px}.ysm-header{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:20px}.ysm-header h2{margin:0;font-size:18px}.ysm-header p{margin:8px 0 0;color:var(--text-dim);font-size:12px;line-height:1.7}.ysm-layout{display:grid;grid-template-columns:minmax(240px,340px) minmax(0,1fr);gap:24px}.ysm-preview{height:440px;min-width:0;border:1px solid var(--border);border-radius:14px;overflow:hidden;background:radial-gradient(ellipse at center,var(--accent-soft),transparent 75%)}.ysm-empty{height:100%;display:grid;place-items:center;padding:25px;box-sizing:border-box;text-align:center;color:var(--text-dim);font-size:12px;line-height:1.9}.ysm-form{display:flex;flex-direction:column;gap:17px;min-width:0}.ysm-form>label:not(.ysm-switch){display:grid;gap:8px;font-size:12px;color:var(--text-dim)}select{width:100%;min-width:0;padding:10px 12px;background:var(--card-2);color:var(--text);border:1px solid var(--border);border-radius:8px;font:inherit;font-size:12px}.ysm-summary{display:flex;gap:10px}.ysm-summary span{padding:5px 9px;border-radius:7px;background:var(--accent-soft);color:var(--accent-2);font-size:11px}.ysm-switch{display:flex;justify-content:space-between;align-items:center;gap:20px;border-top:1px solid var(--border);padding-top:16px}.ysm-switch b{font-size:12px;font-weight:500}.ysm-switch small{display:block;color:var(--text-dim);font-size:11px;line-height:1.7;margin-top:5px}.ysm-note{font-size:11px;color:var(--text-dim);line-height:1.9;margin:0}.ysm-error{color:var(--danger);font-size:12px;line-height:1.8;overflow-wrap:anywhere}.ysm-target{color:var(--text-dim);font-size:10px}.btn{font:inherit;font-size:12px;padding:10px 13px;border-radius:9px;cursor:pointer;white-space:nowrap}.btn-primary{background:var(--accent);color:#fff;border:0}.btn-ghost{color:var(--text);background:var(--card-2);border:1px solid var(--border)}button:disabled{opacity:.45;cursor:not-allowed}@media(max-width:800px){.ysm-layout{grid-template-columns:1fr}.ysm-preview{height:330px}.ysm-header{align-items:flex-start}.default-ysm{padding:16px}}</style>
